(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ht"] = {"ui":{"skip":"Ale nan kontni a","back":"← Tounen sou AI-gile","lang.button":"Lang: {name}","lang.dialog":"Chwazi yon lang","lang.search":"Chèche lang","lang.none":"Pa gen lang ki koresponn","lang.notYet":"{name} poko tradui","theme.aria":"Chanje tèm: klè, fènwa oswa nwa","theme.toLight":"Pase sou tèm klè","theme.toDark":"Pase sou tèm fènwa","theme.toBlack":"Pase sou tèm nwa (nwa toutbon, dous pou ekran OLED)","words.underline":"Souliye mo sa yo sou paj la","words.underlineHelp":"Pase sourit la sou yon mo ki gen pwen anba l, oswa tape l, pou w wè sa l vle di.","words.col.todo":"Kat yo chwazi pou kounye a: ekip la ap kòmanse ak yo yo apre.","words.col.doing":"Yon AI ap travay sou kat sa a kounye a.","words.col.review":"Yon AI fini travay la; yon lòt verifye l anvan li rive jwenn ou.","words.col.verify":"Ap tann ou: eseye l epi di si l mache.","words.col.team":"Nòt oswa repons ou yo, k ap tann ekip la pran yo.","words.col.done":"Fini epi aksepte.","index.title":"AI-gile: ekip devlopman AI ou a, sou yon sèl tablo","index.description":"AI-gile se yon tablo kanban pou ekip AI ki kode. Yo travay pandan w ap dòmi; ou jwenn yon ti pil kout ak bagay pou ou deside, teste ak aksepte.","hero.logoAlt":"Ikòn tablo AI-gile","hero.h1.html":"Ekip devlopman AI ou a, sou yon sèl&nbsp;tablo.","hero.alpha":"🐣 Pre-alfa fèmen","hero.alphaTitle":"Li bonè e li poko fini: mèsi paske w ap eseye li!","hero.lede":"Yo bati pandan w ap dòmi. Ou reveye sou yon ti pil kout: kèk kesyon, kèk bagay pou teste, yon dyaman koulè wouj violèt oswa de. Klike, aksepte, retounen bò kafe w la.","dl.windows":"Aplikasyon Windows","dl.browser":"Sèvi ak li nan navigatè w","dl.messenger":"📱 Messenger pou telefòn ou","dl.soon":"Talè konsa","dl.notify":"🔔 Di m lè l ouvè","dl.notifySmall":"Alfa oswa beta","hero.secondary":"Agile, men ekip la pa bezwen kafe stand-up. (Yo fè stand-up kanmenm.)","pitch.h2":"AI-gile an kantite mo ou vle","pitch.lede":"Chwazi yon longè, soti nan yon sèl mo rive 144. Chak longè gen pwòp deskripsyon li, ekri espesyalman pou gwosè sa a. Glise kourseur a oswa sèvi ak flèch yo.","pitch.rangeLabel":"Longè an mo","pitch.dice":"🎲 yon lòt vèsyon","pitch.words.one":"{n} mo","pitch.words.other":"{n} mo","pitch.letters.one":"{n} lèt","pitch.letters.other":"{n} lèt","pitch.chars.one":"{n} karaktè","pitch.chars.other":"{n} karaktè","count.line.html.one":"{n} kat sou tablo a kounye a","count.line.html.other":"{n} kat sou tablo a kounye a","people.humans.html.one":"👥 {n} moun","people.humans.html.other":"👥 {n} moun","people.agents.html.one":"🤖 {n} ajan","people.agents.html.other":"🤖 {n} ajan","people.working.html.one":"⚡ {n} ap travay kounye a","people.working.html.other":"⚡ {n} ap travay kounye a","pre.title":"AI-gile: gen yon bagay k ap bati","pre.description":"Gen yon bagay k ap bati isit la. Yon tablo kote ekip AI bati sa ou mande, epi yo aprann ou pandan y ap travay. Pou kounye a, se yon pre-alfa fèmen ak zanmi.","pre.h1":"Gen yon bagay k ap bati isit la. 🤫","pre.line":"Yon tablo kote ekip AI bati sa ou mande, epi yo aprann ou pandan y ap travay. Pou kounye a, se yon pre-alfa fèmen ak zanmi.","pre.btn":"🔔 Di m lè l ouvè","pre.peek":"Dèyè vit la: vrè tablo a, an dirèk. Chak kat se yon ba ki gen koulè.","pre.peekFake":"Dèyè vit la: men ki jan yon tablo k ap travay sanble.","pre.night":"🌙 Gadyen nwit la an chaj · 😴 moun nan ap repoze","features.aria":"Sa li fè","f.pile.h":"Yon sèl pil pou ou","f.pile.html":"<b>Pou ou</b> gen tout sa k ap tann ou, nan tout pwojè yo: kesyon, bagay pou teste, travay sèlman yon moun ka fè. Lis ou a di ki sa ki vini apre ak konbyen tan sa pran.","f.sleep.h":"Ekip ki travay pandan w ap dòmi","f.sleep.p":"Chak pwojè gen yon chèf ak yon ekip ajan AI. Kite yon kòmantè sou yon kat, ekip la reveye, fè travay la, epi remèt li ba ou ak etap yon moun fatige ka swiv.","f.tester.h":"Yon testè AI tcheke anvan","f.tester.p":"Anvan anyen rive jwenn ou, yon testè swiv etap yo nan yon kopi aplikasyon an epi montre sa l te wè, ak yon foto ekran. Pase sou sa ki pase yo epi aksepte yo ak yon sèl klik.","f.proof.h":"Prèv, pa pwomès","f.proof.p":"Chak remiz montre sa ki chanje: fichye yo, diff la, foto ekran yo. Ou pa bezwen louvri chak aplikasyon pou konnen si li fini.","f.chat.h":"Pale ak chèf ou yo","f.chat.p":"Yon ba sou kote ki sanble ak Discord: yon ikòn pou chak pwojè, dyaman koulè wouj violèt pou sa ki bezwen ou. Voye yon chèf yon lide; li fè kat ak yon plan ladan l, ak yon bouton ✅ Go.","f.tidy.h":"Li ranje tèt li","f.tidy.p":"Kat ki gen rapò fusyone nan yon sèl, tit ki mele korije, epi yon tcheke token kenbe kòd la lejè. Mwens bagay pou w ale vini ant yo, mwens pou w panse.","f.private.h":"Pou ou, sou òdinatè w","f.private.li1":"Tablo a mache sou pwòp machin ou epi li reponn ou sèlman.","f.private.li2":"Mesaj prive ant moun yo chifre de bout an bout.","f.private.li3":"Okenn kont, okenn pisteur, okenn cookie.","f.lang.h":"Nan lang ou","f.lang.p":"Plis pase 120 lang, soti nan Olandè, Galwa ak Japonè rive nan pirat, Yoda ak Klingon, ak yon chanjman rapid pou tounen nan Anglè pou jagon pwofesyonèl la.","f.service.h":"Soti nan yon ide rive nan yon vrè sèvis","f.service.p":"Ou bati yon bagay ak AI moun ap sèvi ak li kounye a? Make l kòm yon sèvis epi tablo a ede w fè l mache byen: verifikasyon uptime, yon paj estati piblik, ensidan ak yon rapò ekri, chanjman ki bezwen yon Ale, sovgad yo tcheke chak jou. Èd montre w chak etap pandan w ap avanse.","msgr.h2":"AI-gile Messenger: ekip ou nan pòch ou","msgr.p1":"Pale ak ekip AI ou san ou pa ouvri tablo a. Chat ak chèf pwojè ou yo ak zanmi ou, epi gade etap tès yon kat e reponn yo, tout sa sou telefòn ou.","msgr.p2":"Pou konekte l, eskane yon kòd QR sou tablo ou. Premye fwa? Yon chat demo byen janti ap fè w vizite.","msgr.when":"Android an premye, apre sa yon vèsyon web pou telefòn ak iPhone.","msgr.who":"Chèf pwojè ou","msgr.b1":"Koreksyon mòd fè nwa a pare. Ou vle etap tès yo?","msgr.b2":"Wi, tanpri!","msgr.b3":"1. Ouvri Paramèt. 2. Chwazi Fè nwa. Èske li sanble byen?","tl.aria":"Liy tan soti nan premye konvèsasyon an rive nan plan an","tl.h2":"Soti nan premye chita pale a rive nan sa k ap vini","tl.lede":"Dat ak lè reyèl, nan pwòp fizo orè ou. Apre jodi a, se plan an, san okenn dat pwomèt.","tl.today":"Jodi a","tl.planned":"planifye","tl.doing":"an kou","tl.cards.one":"{n} kat","tl.cards.other":"{n} kat","join.h2":"Vin patisipe","join.lede":"Se yon nèg dwòl ki gen bab, AuDHD ak kèk batay ak sante mantal li, ansanm ak anpil ajan pasyan, k ap bati AI-gile. Pou kounye a li prive, nan yon alfa fèmen ak zanmi. Ou ta renmen eseye l lè l ouvè?","join.btn":"Make enterè m","join.small":"N ap ekri ou pa imèl, pa gen lòt bagay","footer.tag":"AI-gile. Okenn pisteur, okenn cookie, okenn kafe stand-up.","footer.licence":"Lisans biznis","footer.status":"Eta","footer.privacy":"Sa nou kenbe","footer.thanks":"Apèl gras a ChilledChat","form.sending":"Ap voye…","form.failed":"Sa pa mache: eseye ankò pita.","form.offline":"Pa t ka rive jwenn AI-gile: eseye ankò pita.","form.keep":"Nou sèvi ak sa sèlman pou n reponn ou, apre sa nou efase l. Okenn pisteur, okenn cookie.","form.keepLink":"Sa nou kenbe","interest.title":"AI-gile: di m lè alfa a ouvè","interest.description":"Kite imèl ou pou konnen kilè alfa oswa beta fèmen AI-gile a ouvè.","interest.h1":"🔔 Di m lè l ouvè","interest.lede":"AI-gile nan pre-alfa fèmen. Kite imèl ou epi n ap ekri ou yon sèl fwa, lè gen yon plas pou ou.","interest.email":"Imèl ou","interest.which":"Ki tès?","interest.alpha":"Alfa fèmen: bonè, brit, anpil chanjman","interest.beta":"Beta: pi estab, pita","interest.both":"Nenpòt, sa ki rive anvan","interest.submit":"Mete m sou lis la","interest.thanks":"Mèsi! Ou sou lis la.","licence.title":"AI-gile: lisans biznis","licence.description":"Ou sèvi ak AI-gile nan biznis ou? Mande yon lisans biznis gratis.","licence.h1":"📜 Lisans biznis","licence.lede":"Ou sèvi ak AI-gile nan travay? Di nou ki moun ou ye ak sa w fè. Si l fè kèk bon, lisans lan gratis.","licence.company":"Konpayi","licence.website":"Sitwèb","licence.what":"Sa w fè","licence.how":"Ki jan sa ede mond lan","licence.email":"Imèl","licence.submit":"Aplike","licence.thanks":"Mèsi! N ap reponn ou pa imèl.","status.title":"Eta AI-gile","status.h1":"Eta AI-gile","status.quiet":"Tout bagay kalm","status.intro":"Èske AI-gile ap mache kounye a? Paj sa a verifye sit entènèt la, pataj tablo, apèl yo ak telechajman an chak 5 minit.","status.up":"Ap mache (li reponn nan {ms} ms)","status.slow":"Li pa t reponn dènye verifikasyon an, n ap eseye ankò","status.down":"An pann: li pa t reponn de dènye verifikasyon yo","status.svc.web":"Sit entènèt","status.svc.web.offers":"Sit sa a: sa AI-gile ye, ak fòm enterè a","status.svc.boards":"Pataj tablo","status.svc.boards.offers":"Tablo piblik, mesaj ant zanmi ak envitasyon","status.svc.calls":"Apèl","status.svc.calls.offers":"Vwa, videyo ak pataj ekran nan AI-gile","status.svc.download":"Telechajman","status.svc.download.offers":"Enstalatè Windows la ak lyen envitasyon yo","status.checking":"Ap verifye…","status.offline":"Pa ka rive jwenn sèvis eta a kounye a (n ap eseye ankò)","status.updated":"mete ajou {ago}","status.justNow":"kounye a menm","status.min":"{n} min de sa","status.hours":"{n} è de sa","status.days":"{n} jou de sa","privacy.title":"AI-gile: sa nou kenbe","privacy.h1":"Sa nou kenbe","privacy.lede":"An kout: sèlman sa ou voye ban nou, epi pa pou lontan.","privacy.only":"Sèlman sa ou voye ban nou: sa ou tape nan yon fòm, tankou imèl ou. Anyen lòt sou ou.","privacy.sealed":"Li sele pou sèvè nou an pa ka li l: nan navigatè w anvan li pati (sou yon navigatè ki pi ansyen, menm moman li rive a). Se sèlman pwòp tablo pa nou ki ka louvri l.","privacy.server":"Li efase sou sèvè a depi li rive sou tablo nou an. Tout sa ki toujou la apre 30 jou efase kanmenm.","privacy.board":"Nou kenbe l sou tablo nou an sèlman jiskaske nou reponn ou, apre sa nou efase l la tou.","privacy.none":"Okenn pisteur, okenn cookie, okenn analitik.","privacy.local":"Lang ou ak chwa limyè oswa fènwa ou rete nan pwòp navigatè w. Yo pa janm voye yo ban nou.","privacy.ask":"Ou vle l disparèt pi vit? Reponn imèl nou an epi di nou sa.","live.h2":"Gade l ap bati, an dirèk","live.caption":"Chak kat kache: ou wè fòm travay la, pa mo yo.","live.watching.one":"an dirèk: {n} ap gade","live.watching.other":"an dirèk: {n} ap gade","live.last.now":"Dènye kat la deplase jis kounye a","live.last.min.one":"Dènye kat la deplase {n} minit de sa","live.last.min.other":"Dènye kat la deplase {n} minit de sa","live.last.hour.one":"Dènye kat la deplase {n} è de sa","live.last.hour.other":"Dènye kat la deplase {n} è de sa","live.last.day.one":"Dènye kat la deplase {n} jou de sa","live.last.day.other":"Dènye kat la deplase {n} jou de sa","live.offline":"Tablo an dirèk la ap pran yon ti repo. Tounen talè.","live.cols":"Backlog|Pou fè|Ap fèt|Ekip la ap verifye|Pou ou test|Pou ekip la|Fini"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robo.","Delege."]},{"n":2,"texts":["Kanban robo.","Ajan, òganize.","Lide, bati."]},{"n":3,"texts":["Kanban pou robo.","Lide vin fonksyon.","Kanban ajan gratis."]},{"n":5,"texts":["Yon tablo kanban ajan jere.","Ou ekri kat. Ajan bati.","Gratis, lokal, teste, tikotan fou."]},{"n":8,"texts":["Yon tablo kanban gratis kote ajan AI travay.","Ekri yon lide. Ajan yo bati l. Ou aksepte.","Agile pou yon moun ak anpil robo pasyan."]},{"n":13,"texts":["Yon tablo kanban sou òdinatè w kote ajan AI pran kat yo pou travay.","Ekri yon lide. Yon ekip ajan bati l. Yon testè verifye l anvan.","Gratis, san kont, san pisteur: yon tablo, kèk robo, epi ou se chèf la."]},{"n":21,"texts":["AI-gile se yon tablo kanban pou travay ak ajan AI ki kode. Yo pran kat yo; se ou menm ki teste yo epi aksepte yo.","Chak pwojè gen yon chèf ak yon ekip ajan AI. Kite yon kòmantè sou nenpòt kat epi ekip la mete men nan travay.","Yon tablo tach pèsonèl, gratis, ki mache sou pwòp òdinatè w. Se robo ki travay. Se ou ki di wi."]},{"n":34,"texts":["Ou mete lide sou yon tablo. Yon ekip ajan AI transfòme yo an fonksyon ki mache, teste yo, epi remèt yo ba ou ak etap pou eseye. Anyen pa konte kòm fini toutotan ou pa di sa.","AI-gile se yon tablo kanban fèt lakay Rich te bati ak anpil èd ajan li jere kounye a yo. Li gratis, li mache sou òdinatè w, epi li pataje ak zanmi, li pa vann.","Imajine yon tablo kanban òdinè, ak kolòn ki soti nan Backlog rive nan Fini, sof ke se ajan AI k ap pran kat yo. Yo rapòte pwogrè, yo poze kesyon lè yo bloke, epi yo toujou tann dwèt chita w anlè."]},{"n":55,"texts":["AI-gile se yon tablo kanban kote ekip la fèt ak ajan AI. Chak pwojè gen yon chèf ki planifye travay la ak èdè ki bati l. Lè yon fonksyon pare, yon testè AI eseye l epi pran yon foto ekran, answit li rive nan pil ou a. Aksepte l, oswa kite yon kòmantè epi yo refè l.","Li te kòmanse kòm yon fason pou yon moun swiv anpil sesyon kodaj AI an menm tan, epi li grandi an yon vrè tablo. Li mache sou machin ou, li pa mande okenn kont, epi li pa gen pisteur. Li gratis pou zanmi ak nenpòt moun ki gen kiryozite. Li poko fini tou, kidonk atann w ak kèk kote ki brit ak kèk sipriz.","Men vèsyon onèt la. Ou toujou dwe gen lide yo, epi ou toujou dwe tcheke rezilta yo. Sa AI-gile fè se tout sa ki nan mitan: li kenbe kat yo nan lòd, li reveye bon ajan an lè w kite yon kòmantè, li montre egzakteman sa ki chanje, epi li mete tout sa nan yon sèl pil kout pou ou."]},{"n":89,"texts":["AI-gile se yon tablo kanban gratis ou fè mache sou pwòp òdinatè w. Olye de moun, chak pwojè gen yon ekip ajan AI: yon chèf ki fè lide ou yo tounen kat ak yon plan, ak èdè ki pran kat yo dapre priyorite. Lè yon bagay bati, yon testè AI swiv etap tès yo epi montre w sa l te wè. Answit li rete tann nan yon sèl pil ki rele Pou ou. Ou aksepte l, oswa ou kite yon kòmantè epi ekip la eseye yon lòt fwa. Anyen pa janm rive nan Fini san ou.","Kèk bagay ou pa t ap atann. Yon gadyen mennen kolòn Pou fè a plen pandan w ap dòmi, li chwazi kat ki pa bezwen repons ou. Yon konteur token montre konbyen ajan yo sèvi jodi a ak semèn sa a, epi Mòd San Token di yo sispann depanse. Ou ka voye mesaj bay zanmi, epi mesaj prive yo chifre de bout an bout. Tablo a pale anviwon 120 lang, ansanm ak Olandè, Flamann, pirat ak Klingon. Pa gen anyen ki koute yon santim, epi pèsonn pa eseye vann ou l.","AI-gile se yon ti pwojè pèsonèl, se pa yon konpayi. Rich te vle okipe plizyè pwojè kodaj AI san l pa louvri chak aplikasyon pou tcheke yo, konsa li menm ak ajan yo bati yon tablo pou sa, answit yo sèvi ak tablo sa a pou bati rès tèt li. Li nan pre-alfa fèmen, sa vle di li mache, plis oswa mwens, pou yon ti pwiyen zanmi. Pa gen paj pri, pa gen bilten, epi pa gen plan kwasans. Si sa sanble itil, ou ka mande pou eseye l lè l ouvè yon ti jan plis."]},{"n":144,"texts":["AI-gile se yon tablo kanban pou yon moun ak anpil ajan AI. Li mache sou pwòp òdinatè w epi li totalman gratis. Ou ajoute pwojè, epi chak pwojè jwenn yon chèf ak yon ti ekip. Ou pale ak chèf la, yon ti jan tankou sou Discord, epi ou dekri yon lide; chèf la fè l tounen kat ak yon plan, answit li tann ou peze Go. Ekip la pase sou kat yo dapre priyorite, ak yon liy kòmand senp ki fèt pou modèl lang. Anvan anyen tounen jwenn ou, yon testè AI swiv etap yo nan yon kopi aplikasyon an epi tache yon foto ekran. Travay ki fini rive nan pil ou a ak fichye ki chanje yo ak diff la. Ou aksepte l, oswa ou kite yon kòmantè epi ekip la reveye pou eseye ankò. Se sèlman ou ki ka mete yon kat nan Fini.","Men apeprè ki jan yon jou ak AI-gile ye. Nan aswè ou kite kèk kòmantè: bouton sa a nan move kote, lis sa a dwe klase, èske nou ta ka gen yon mòd fènwa. Ou ale dòmi. Ajan yo li kòmantè yo, fè chanjman yo, teste yo epi remèt yo ba ou. Si Pou fè a vin vid, gadyen an ranpli l ak kat nan backlog ki pa bezwen repons ou. Nan maten gen yon sèl pil kout: de twa kesyon ak kèk bagay pou eseye, chak ak etap yon moun ki gen dòmi ka swiv ak yon foto ekran ki montre l ap mache. Ou klike sou yo, aksepte bon yo epi voye rès la tounen. Yon konteur token montre sa tout bagay sa a te sèvi, epi Mòd San Token la pou semèn kote ou bezwen ekonomize. Answit ou manje maten, bagay ajan yo poko ka ede ou ak li.","Pou kòmanse, sa AI-gile pa ye. Se pa yon startup, li pa pou vann, epi pèsonn pa ranmase done ou yo. Se yon tablo gratis ki mache sou òdinatè w, san kont, san pisteur epi san cookie. Sa li ye: yon sèl kote ranje pou wè tout pwojè kodaj AI ou yo alafwa, ak yon ekip ajan k ap fè kat yo epi ou menm k ap pran desizyon yo. Li fusyone kat ki gen rapò, li korije tit ki mele, epi li veye pou kòd la rete lejè. Li pale anviwon 120 lang, soti nan Olandè ak Flamann rive nan pirat ak Klingon. Zanmi ka voye mesaj bay youn lòt, an prive epi chifre. Se Rich ak anpil ajan pasyan ki bati l, pi fò tan ap sèvi ak li menm. Li nan pre-alfa fèmen, kidonk li brit kèk kote. Si sa sanble amizan, mande l byen epi petèt w ap antre bonè."]}],"quips":{"1":"Yon sèl mo. Ak kouraj. Petèt twòp kouraj.","3":"Twa mo. Deja pi onèt pase pifò paj pwodwi.","8":"Uit mo. Toujou pi kout pase yon stand-up.","21":"Longè yo se pwen istwa, san dout. Natirèlman.","55":"Senkant-senk mo. De kat fini pandan w t ap li sa.","144":"Sa a se pi long lan. Pa gen 233. Ajan yo ale dòmi."}},"timeline":{"first-idea.name":"Premye lide a","first-idea.line":"Premye konvèsasyon an, anvan menm yon sèl liy kòd te egziste.","first-board.name":"Premye tablo","first-board.line":"Yon tablo ki swiv pwòp konstriksyon li: kat, kolòn, trennen epi depoze, pwojè.","team-roles.name":"Ekip ak wòl","team-roles.line":"Pwofil ajan, modèl ekip, espas ak ki moun ki fè kisa.","install.name":"Enstalasyon ak vèsyon","install.line":"Yon zip yon zanmi ka enstale, mizajou otomatik, kanal ak retounen anndan.","usage-saver.name":"Ekonomi itilizasyon","usage-saver.line":"Mezire sa chak egzekisyon koute, kenbe kòd la lejè, ekonomize limit ou.","friends.name":"Zanmi ak pataj","friends.line":"Mesaj prive, yon relè mele, envitasyon, wòl ak pwojè pataje.","languages.name":"Lang","languages.line":"Chak tèks ekran nan yon fichye lang, ak Olandè ak Flamann an premye.","ai-tester.name":"Testè AI","ai-tester.line":"Yon testè tcheke chak remiz anvan epi montre sa l te wè.","website.name":"Sitwèb la","website.line":"aigile.lol, teaser la ak liy tan sa a.","streaming.name":"Chat ak difizyon an dirèk","streaming.line":"Discord, Twitch, OBS, mòd streamer, GIF ak emoji.","no-ai.name":"Edisyon San AI","no-ai.line":"Yon tablo pou moun ki kode san AI, ak tablo piblik.","night-watch.name":"Gadyen lannwit","night-watch.line":"Yon gadyen ak yon Scrum Master kenbe ekip yo sou travay pandan w ap dòmi.","p-more.name":"Tout rès la","p-more.line":"Ti lide ki toujou ap tann tou pa yo.","p-android.name":"Telefòn ak Android","p-android.line":"Rive jwenn tablo ou a nan yon telefòn, answit yon aplikasyon Android natif.","p-release.name":"Alfa ak apre","p-release.line":"Alfa fèmen, sit la an dirèk, answit beta.","p-languages.name":"Plis lang","p-languages.line":"130 lang, ak yon mòd imèsyon pou moun k ap aprann.","p-engines.name":"Plis motè AI","p-engines.line":"Chwazi Claude, Codex, Gemini, Copilot oswa Cursor pou chak ajan.","p-pro.name":"Pratik pwofesyonèl","p-pro.line":"Etikèt risk, baryè merge, kat ensidan ak ranpa pwoteksyon.","p-self.name":"Pran swen ou","p-self.line":"Mòd fatige, rapèl pou pran swen tèt ou ak 4:20.","p-servers.name":"Sèvè ak kwasans","p-servers.line":"Paramèt sèvè global, wòl ak planifikasyon pou grandi.","p-livestream.name":"Ekstra difizyon","p-livestream.line":"Chat Twitch, emoji pèsonalize ak yon vi dirèk piblik."},"words":{"button":"📖 Jagon pwofesyonèl","h":"📖 Mo eksplike","intro":"Mo ou jwenn nan AI-gile, an mo senp: bati l, chanje l san danje, kenbe l ap mache pou moun k ap sèvi ak li, epi travay an ekip ak AI.","search":"Chèche yon mo…","none":"Pa gen mo ki koresponn.","close":"Fèmen","count":{"one":"{count} mo","other":"{count} mo"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Bati l"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Chanje l san danje"},{"id":"run","name":"🛎️ Fè yon sèvis mache"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lide ak travay ki poko planifye. Anyen la a pa travay jiskaske li deplase nan Pou fè."},{"id":"sprint","g":"agile","word":"Sprint","text":"Yon ti peryòd travay (souvan yon semèn oswa de) ak yon kantite kat ki dakò pou fini.","also":["sprints"]},{"id":"standup","g":"agile","word":"Reyinyon kout","text":"Yon ti pwen rapid: sa chak manm ekip te fè, sa yo pral fè apre, ak sa k ap bloke yo.","also":["standup","stand-ups","stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Yon tablo ak kolòn (Pou fè, Ap fèt, Fini) kote kat yo deplase de goch a dwat pandan travay la ap fèt."},{"id":"wip","g":"agile","word":"Limit WIP","text":"Travay k ap fèt: maksimòm kat yon kolòn ta dwe genyen, pou ekip la fini bagay yo avan l kòmanse plis.","also":["WIP","WIP limit"]},{"id":"dod","g":"agile","word":"Definisyon Fini","text":"Ti lis ekip la sou sa “fini” vle di, tankou teste ak eksplike, anvan yo ba ou yon kat. Marasa l, Definisyon Pare, di ki lè yon kat klè ase pou kòmanse.","also":["Definition of Done","Definisyon Pare","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Yon gade dèyè sou fason ekip la travay, pou dakò sou yon bagay pou fè pi byen. Nan AI-gile yon retro pwopoze yon chanjman nan fason ekip la travay, epi ou di Go oswa Poko.","also":["retros","retrospektiv","retrospective"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Tout moun sou pon an: chak ekip kite lòt travay pou ede sou yon sèl pwojè ijan jiskaske li regle. Lòt pwojè yo tann pandan tan sa a.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Moun ki kenbe travay la ap koule: li wè kat ki bloke, li pouse ekip yo epi li fè ou sonje sa k ap tann. Nan AI-gile, Chèf Scrum Master fè sa nan tout pwojè yo.","also":["Chèf Scrum Master","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Dosye pwojè a ak kòd li ak tout istwa commits li, souvan kenbe tou sou GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Yon liy travay apa nan kòd la, pou ka fè chanjman san manyen vèsyon prensipal la.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Yon foto sove nan kòd la, ak yon ti nòt sou sa ki chanje. Ou ka toujou tounen nan youn.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Voye foto sove yo (commits) soti sou òdinatè sa a rive sou GitHub, pou yo gen kopi ak pou pataje yo."},{"id":"merge","g":"build","word":"Merge","text":"Mete chanjman yon branch tounen nan vèsyon prensipal la."},{"id":"pr","g":"build","word":"Pull request","text":"Mande pou chanjman yon branch verifye epi fizyone nan vèsyon prensipal la.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ranje kòd la san chanje sa li fè: fichye pi piti, non pi klè, mwens repetisyon."},{"id":"bug","g":"build","word":"Bug","text":"Yon bagay ki pa mache jan li ta dwe.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revizyon pa yon kolèg","text":"Yon dezyèm pè je: yon lòt AI tcheke travay chak kat anvan li rive jwenn ou, pou mwens erè pase.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Eseye yon travay fini pou verifye si li fè sa yo te mande a, avan ou aksepte l.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kout pou quality assurance (garanti kalite): verifikasyon otomatik ki fèt anvan anyen ale an liy. Lè QA wouj, yon bagay pa pase, epi li pa ka ale an liy jiskaske yo ranje sa.","also":["verifikasyon kalite","quality checks"]},{"id":"testpile","g":"test","word":"Pil tès","text":"Kat ki fini k ap tann ou eseye yo, youn apre lòt. Aksepte youn oswa voye l tounen ak yon nòt, epi pwochen an parèt.","also":["test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Mete yon nouvo vèsyon an liy, pa egzanp sou yon sèvè kote moun yo sèvi ak li."},{"id":"release","g":"change","word":"Vèsyon","text":"Yon pake travay fini ki gen yon non, ki ale an liy ansanm, ak ti nòt sou sa ki chanje. 🚀 Vèsyon ekri nòt yo apati kat ki fini yo.","also":["vèsyon yo","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Retounen sou dènye vèsyon ki te mache a lè yon nouvo vèsyon bay pwoblèm. Nan AI-gile, li fè yon lis etap pou defèt ki te ekri sou chak chanjman.","also":["roll back","retounen dèyè"]},{"id":"live","g":"change","word":"An liy","text":"Vrè vèsyon moun yo sèvi ak li a, pa yon kopi pou fè esè. Devlopè yo rele l production tou.","also":["live","production","pwodiksyon"],"noTip":1},{"id":"change","g":"change","word":"Chanjman","text":"Yon chanjman planifye sou yon bagay moun konte sou li, ekri davans: ki sa, poukisa, risk la, ki lè, ak ki jan pou defèt li. Kòmanse youn ak 🔀 Leve yon chanjman.","also":["chanjman yo","demann chanjman","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Yon bagay ki ka mal pase, ak yon nòt selon ki chans li genyen pou rive ak ki jan li ta grav. ⚠️ Risk kenbe yo nan yon sèl lis, pi gwo nòt la anvan, chak ak yon dat pou gade l ankò.","also":["risk yo","rejis risk","risk register"]},{"id":"chgwin","g":"change","word":"Fenèt chanjman","text":"Moman lè chanjman ka ale an liy, tankou yon mardi swa trankil. Andeyò yon fenèt, yon kat chanjman pa ka fini, sòf si se yon ijans.","also":["fenèt chanjman yo","change window"]},{"id":"gonogo","g":"change","word":"Ale / Pa ale","text":"Yon vòt rapid jis anvan yon chanjman ale an liy: chak moun ki dwe apwouve di Ale oswa Pa ale. Li avanse sèlman lè yo tout dakò.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Apwobasyon","text":"Tann yon wi anvan travay la kòmanse. Yon kat yon zanmi leve, oswa yon chanjman, ap tann nan ✅ Apwobasyon jiskaske ou apwouve l oswa refize l.","also":["apwobasyon yo","approval"]},{"id":"quiettime","g":"change","word":"Moman trankil","text":"Yon peryòd, tankou yon stream, yon demo oswa lannwit, kote anyen pa ale an liy. Ekip yo kontinye travay ak teste, men ale an liy tann jiskaske li fini. Lòt kote yo rele l change freeze.","also":["moman trankil yo","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Sèvis","text":"Yon bagay ou bati moun konte sou li, tankou yon sit entènèt oswa yon app, ke yo okipe pou l kontinye mache. Tcheke “Pwojè sa a se yon sèvis” epi di sa li ofri, ki moun ki sèvi ak li ak ki moun ki sou gad.","also":["sèvis yo","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Verifikasyon uptime","text":"Yon verifikasyon otomatik, chak kèk minit, pou wè si sèvis ou a toujou reponn. Si li echwe plizyè fwa youn dèyè lòt, AI-gile ouvè yon kat ensidan pou kont li.","also":["uptime","disponiblite"]},{"id":"statuspage","g":"run","word":"Paj estati","text":"Yon paj piblik ki montre si yon sèvis ap mache (vèt, oranj oswa wouj) ak dènye nouvèl la, pou moun k ap sèvi ak li ka gade olye yo mande.","also":["paj estati yo","status page"]},{"id":"desk","g":"run","word":"Biwo sèvis","text":"Kote kesyon ak rapò moun ki itilize sèvis ou a rive. AI-gile klase chak youn kòm demann, ensidan oswa lide, epi li di ou lè li sanble ak yon bagay yo te deja rapòte.","also":["biwo sèvis yo","biwo èd","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Demann sèvis","text":"Yon moun k ap mande yon bagay nòmal, tankou yon nouvo kont oswa yon ti èd, olye l rapòte gen yon bagay ki kraze. Li tann tou pa l; yon ensidan pase anvan.","also":["demann sèvis yo"]},{"id":"incident","g":"run","word":"Ensidan","text":"Yon bagay ki kase kounye a pou moun k ap sèvi ak li, tankou sit entènèt la ki tonbe. Yon kat 🔥 ensidan pase devan liy lan: fè l mache ankò se premye bagay.","also":["ensidan yo","incident"]},{"id":"major","g":"run","word":"Gwo ensidan","text":"Yon ensidan ki grav anpil: anpil moun touche, oswa lajan oswa done an danje. Yon sèl bouton mete tout ekip yo sou li (swarm), reveye moun ki sou gad la epi mande yon nouvèl estati chak 30 minit.","also":["gwo ensidan yo","major incident"]},{"id":"oncall","g":"run","word":"Sou gad","text":"Se ou ki reponn lè yon bagay kase, menm lannwit. Chak sèvis gen yon manm ekip sou gad yo reveye an premye pou ensidan li yo.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Delè pou reponn","text":"Konbyen tan yon kat ka tann yon premye repons, pa egzanp inèdtan pou yon ensidan. Apre sa li jwenn yon revèy wouj, pou anyen pa bliye an silans. Yo rele l objektif repons tou.","also":["objektif repons","response target"]},{"id":"postmortem","g":"run","word":"Post-mòtèm","text":"Yon ti gade dèyè apre yon ensidan: sa ki te pase, sa ki te ede ak sa pou chanje, san blame pèsonn. Yon ensidan pa ka fèmen san li.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Pwoblèm","text":"Kòz kache dèyè youn oswa plizyè ensidan. Yon kat 🧩 pwoblèm rasanble ensidan ki toujou ap tounen, pou yo jwenn kòz la epi ranje l pou tout tan.","also":["pwoblèm yo","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Kòz rasin","text":"Vrè rezon yon bagay kase, pa sèlman sa ou te wè k ap mal mache. Ranje kòz rasin lan epi ensidan an sispann tounen.","also":["root cause"]},{"id":"workaround","g":"run","word":"Solisyon tanporè","text":"Yon fason pou kenbe bagay yo ap mache jiskaske vrè reparasyon an pare, tankou rekòmanse yon bagay lè li bloke. Yo ekri l sou kat pwoblèm lan pou pèsonn pa oblije chèche l ankò.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Erè ki konnen","text":"Yon pwoblèm yo konprann kòz li epi ki gen yon solisyon tanporè, men yo poko ranje l. 🧩 Erè ki konnen fè lis yo, pou tout moun sèvi ak solisyon tanporè a olye yo fouye ankò.","also":["erè yo konnen","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Enstriksyon etap pa etap pou ranje yon kalite pwoblèm yo konnen, pou yo fè l menm jan, vit, chak fwa. Apre yon gwo ensidan ekip la ka pwopoze ou youn pou ou bay OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Eleman konfigirasyon","text":"Yon bagay sèvis ou a depann de li, tankou yon sèvè, yon domèn, yon sètifika, yon kle oswa yon founisè. 🗂️ Eleman konfigirasyon fè lis yo pou chak sèvis, pou ou ka wè sa yon ensidan afekte ak sa ki bezwen renouvle oswa sovgade.","also":["eleman konfigirasyon yo","configuration item"]},{"id":"expiry","g":"run","word":"Dat ekspirasyon","text":"AI-gile veye dat tankou lè yon sètifika oswa yon domèn ap fini. Nan 30 jou anvan dat la li fè yon kat pou renouvle l, pou anyen pa sispann mache san atann.","also":["dat ekspirasyon yo","ekspirasyon","siveyans ekspirasyon"]},{"id":"backup","g":"run","word":"Sovgad","text":"Yon kopi done ou te sere pi bonè, pou ou ka retounen sou li si yon bagay pèdi oswa abime. AI-gile fè yon sovgad tablo ou yo chak jou.","also":["sovgad yo","backup","backups"]},{"id":"restore","g":"run","word":"Retabli","text":"Remete done apati yon sovgad. Yon sovgad konte vrèman sèlman lè ou konnen li ka retabli, kidonk li vo lapenn eseye sa de tanzantan.","also":["retabli l","restore"]},{"id":"svcreview","g":"run","word":"Revizyon sèvis","text":"Yon gade dèyè sou yon mwa nan yon sèvis: ensidan ki louvri ak ki ranje, ki jan moun yo te jwenn repons vit, uptime ak tokèn ki sèvi. Revizyon chak mwa a montre sa pou chak sèvis.","also":["revizyon sèvis yo","revizyon chak mwa","revizyon mansyèl"]},{"id":"accessreview","g":"run","word":"Revizyon aksè","text":"Verifye chak 90 jou ki moun ki ka toujou antre: lyen pataj, wòl zanmi ak sekrè ki kenbe. Ou kenbe oswa retire chak youn, pou ansyen aksè pa rete kole.","also":["revizyon aksè yo"]},{"id":"improvements","g":"run","word":"Lis amelyorasyon","text":"Tout sa ekip la deside amelyore, nan yon sèl kote: sijesyon retro, aksyon revizyon ak reparasyon pwoblèm, chak ak estati li. Ou jwenn li anba 📈 Amelyorasyon.","also":["lis amelyorasyon yo","amelyorasyon"]},{"id":"tokencap","g":"run","word":"Limit tokèn","text":"Yon limit chak mwa sou tokèn ajan yon sèvis ka itilize. A 80% ou resevwa yon avètisman; a 100% travay yo fè an aryèplan tann mwa pwochen oswa jiskaske ou monte limit lan.","also":["limit tokèn yo","token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Ajan","text":"Yon AI ki travay poukont li sou yon travay: li li kòd la, li fè chanjman, li egzekite verifikasyon, epi li rapòte.","also":["agent","agents","ajan"]},{"id":"token","g":"ai","word":"Token","text":"Inite yo konte itilizasyon AI ladan l: apeprè kèk lèt tèks ki li oswa ki ekri. Mwens token, plis plan ou rete.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Yon ti kòmand ki mache poukont li nan yon moman presi, egz. lè yon sesyon AI kòmanse, pou ekip la tande kòmantè ou yo.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
